export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-18\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 18,\n    \"title\": \"難一\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 14,\n    \"passageIds\": [\n      \"han-fei-zi_ch-18_p-1\",\n      \"han-fei-zi_ch-18_p-2\",\n      \"han-fei-zi_ch-18_p-3\",\n      \"han-fei-zi_ch-18_p-4\",\n      \"han-fei-zi_ch-18_p-5\",\n      \"han-fei-zi_ch-18_p-6\",\n      \"han-fei-zi_ch-18_p-7\",\n      \"han-fei-zi_ch-18_p-8\",\n      \"han-fei-zi_ch-18_p-9\",\n      \"han-fei-zi_ch-18_p-10\",\n      \"han-fei-zi_ch-18_p-11\",\n      \"han-fei-zi_ch-18_p-12\",\n      \"han-fei-zi_ch-18_p-13\",\n      \"han-fei-zi_ch-18_p-14\",\n      \"han-fei-zi_ch-18_p-15\",\n      \"han-fei-zi_ch-18_p-16\",\n      \"han-fei-zi_ch-18_p-17\",\n      \"han-fei-zi_ch-18_p-18\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 1,\n      \"canonicalText\": \"晉文公將與楚人戰，召舅犯問之，曰：「吾將與楚人戰，彼眾我寡，為之奈何？」舅犯曰：「臣聞之，繁禮君子，不厭忠信；戰陣之閒，不厭詐偽。君其詐之而已矣。」文公辭舅犯，因召雍季而問之，曰：「我將與楚人戰，彼眾我寡，為之奈何？」雍季對曰：「焚林而田，偷取多獸，後必無獸；以詐遇民，偷取一時，後必無復。」文公曰：「善。」辭雍季，以舅犯之謀與楚人戰以敗之。歸而行爵，先雍季而後舅犯。群臣曰：「城濮之事，舅犯謀也，夫用其言而後其身可乎？」文公曰：「此非君所知也。夫舅犯言，一時之權也；雍季言，萬世之利也。」仲尼聞之，曰：「文公之霸也宜哉！既知一時之權，又知萬世之利。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-1_s-1\",\n        \"han-fei-zi_ch-18_p-1_s-2\",\n        \"han-fei-zi_ch-18_p-1_s-3\",\n        \"han-fei-zi_ch-18_p-1_s-4\",\n        \"han-fei-zi_ch-18_p-1_s-5\",\n        \"han-fei-zi_ch-18_p-1_s-6\",\n        \"han-fei-zi_ch-18_p-1_s-7\",\n        \"han-fei-zi_ch-18_p-1_s-8\",\n        \"han-fei-zi_ch-18_p-1_s-9\",\n        \"han-fei-zi_ch-18_p-1_s-10\",\n        \"han-fei-zi_ch-18_p-1_s-11\",\n        \"han-fei-zi_ch-18_p-1_s-12\",\n        \"han-fei-zi_ch-18_p-1_s-13\",\n        \"han-fei-zi_ch-18_p-1_s-14\",\n        \"han-fei-zi_ch-18_p-1_s-15\",\n        \"han-fei-zi_ch-18_p-1_s-16\",\n        \"han-fei-zi_ch-18_p-1_s-17\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"晉文公將與楚人戰，召舅犯問的，說道：吾將與楚人戰，彼眾我寡，為的奈何？舅犯說道：臣屬聞的，繁禮國君子，不厭忠信；戰陣的閒，不厭詐偽。國君他的詐的而且已矣。文公辭舅犯，因召雍季而且問的，說道：我將與楚人戰，彼眾我寡，為的奈何？雍季對說道：焚林而且田，偷取多獸，後必無獸；以詐遇民，偷取一時，後必無復。文公說道：善。辭雍季，以舅犯的謀與楚人戰以敗的。歸而且行爵，先雍季而且後舅犯。群臣屬說道：城濮的事，舅犯謀啊，夫用他的言而且後他的身可乎？文公說道：此絕不是國君所知啊。夫舅犯言，一時的權啊；雍季言，萬世的利啊。仲尼聞的，說道：文公的霸啊宜哉！既知一時的權，又知萬世的利。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「晉文公將與楚人戰，召舅犯問之，曰：「吾將與楚人戰，彼眾我寡，為之奈何」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「晉」、「文」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「晉文公將與楚人戰召舅犯問之曰吾將與楚人戰彼眾我寡」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」舅犯曰：「臣聞之，繁禮君子，不厭忠信」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 2,\n      \"canonicalText\": \"或曰：雍季之對，不當文公之問。凡對問者，有因問小大緩急而對也，所問高大而對以卑狹，則明主弗受也。今文公問以少遇眾，而對曰「後必無復」，此非所以應也。且文公不知一時之權，又不知萬世之利。戰而勝，則國安而身定，兵強而威立，雖有後復，莫大於此，萬世之利，奚患不至？戰而不勝，則國亡兵弱，身死名息，拔拂今日之死不及，安暇待萬世之利？待萬世之利在今日之勝，今日之勝在詐於敵，詐敵，萬世之利而已。故曰：雍季之對不當文公之問。且文公又不知舅犯之言，舅犯所謂不厭詐偽者，不謂詐其民，請詐其敵也。敵者，所伐之國也，後雖無復，何傷哉？文公之所以先雍季者，以其功耶？則所以勝楚破軍者，舅犯之謀也；以其善言耶？則雍季乃道其後之無復也，此未有善言也。舅犯則以兼之矣。舅犯曰「繁禮君子，不厭忠信」者，忠、所以愛其下也，信、所以不欺其民也。夫既以愛而不欺矣，言孰善於此？然必曰出於詐偽者，軍旅之計也。舅犯前有善言，後有戰勝，故舅犯有二功而後論，雍季無一焉而先賞。「文公之霸，不亦宜乎，」仲尼不知善賞也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-2_s-1\",\n        \"han-fei-zi_ch-18_p-2_s-2\",\n        \"han-fei-zi_ch-18_p-2_s-3\",\n        \"han-fei-zi_ch-18_p-2_s-4\",\n        \"han-fei-zi_ch-18_p-2_s-5\",\n        \"han-fei-zi_ch-18_p-2_s-6\",\n        \"han-fei-zi_ch-18_p-2_s-7\",\n        \"han-fei-zi_ch-18_p-2_s-8\",\n        \"han-fei-zi_ch-18_p-2_s-9\",\n        \"han-fei-zi_ch-18_p-2_s-10\",\n        \"han-fei-zi_ch-18_p-2_s-11\",\n        \"han-fei-zi_ch-18_p-2_s-12\",\n        \"han-fei-zi_ch-18_p-2_s-13\",\n        \"han-fei-zi_ch-18_p-2_s-14\",\n        \"han-fei-zi_ch-18_p-2_s-15\",\n        \"han-fei-zi_ch-18_p-2_s-16\",\n        \"han-fei-zi_ch-18_p-2_s-17\",\n        \"han-fei-zi_ch-18_p-2_s-18\",\n        \"han-fei-zi_ch-18_p-2_s-19\",\n        \"han-fei-zi_ch-18_p-2_s-20\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：雍季的對，不當文公的問。凡對問的人或事，有因問小大緩急而且對啊，所問高大而且對以卑狹，則明主弗受啊。今文公問以少遇眾，而且對說道：後必無復，此絕不是所以應啊。且文公不知一時的權，又不知萬世的利。戰而且勝，則國安而且身定，兵強而且威立，雖有後復，莫大於此，萬世的利，奚患不至？戰而且不勝，則國亡兵弱，身死名息，拔拂今日的死不及，安暇待萬世的利？待萬世的利在今日的勝，今日的勝在詐於敵，詐敵，萬世的利而且已。因此韓絕不是子評論說道：雍季的對不當文公的問。且文公又不知舅犯的言，舅犯所謂不厭詐偽的人或事，不謂詐他的民，請詐他的敵啊。敵的人或事，所伐的國啊，後雖無復，何傷哉？文公的所以先雍季的人或事，以他的功耶？則所以勝楚破軍的人或事，舅犯的謀啊；以他的善言耶？則雍季乃道他的後的無復啊，此未有善言啊。舅犯則以兼的矣。舅犯說道：繁禮國君子，不厭忠信的人或事，忠、所以愛他的下啊，信、所以不欺他的民啊。夫既以愛而且不欺矣，言孰善於此？然必說道：出於詐偽的人或事，軍旅的計啊。舅犯前有善言，後有戰勝，所以舅犯有二功而且後論，雍季無一焉而且先賞賜。文公的霸，不亦宜乎，仲尼不知善賞賜啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：雍季之對，不當文公之問」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「雍」、「季」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰雍季之對不當文公之問凡對問者有因問小大緩急而」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「凡對問者，有因問小大緩急而對也，所問高大而對以卑狹，則明主弗受也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 3,\n      \"canonicalText\": \"歷山之農者侵畔，舜往耕焉，期年，甽畝正。河濱之漁者爭坻，舜往漁焉，期年，而讓長。東夷之陶者器苦窳，舜往陶焉，期年而器牢。仲尼歎曰：「耕、漁與陶，非舜官也，而舜往為之者，所以救敗也。舜其信仁乎！乃躬藉處苦而民從之，故曰：聖人之德化乎！」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-3_s-1\",\n        \"han-fei-zi_ch-18_p-3_s-2\",\n        \"han-fei-zi_ch-18_p-3_s-3\",\n        \"han-fei-zi_ch-18_p-3_s-4\",\n        \"han-fei-zi_ch-18_p-3_s-5\",\n        \"han-fei-zi_ch-18_p-3_s-6\",\n        \"han-fei-zi_ch-18_p-3_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"歷山的農的人或事侵畔，舜往耕焉，期年，甽畝正。河濱的漁的人或事爭坻，舜往漁焉，期年，而且讓長。東夷的陶的人或事器苦窳，舜往陶焉，期年而且器牢。仲尼歎說道：耕、漁與陶，絕不是舜官啊，而且舜往為的的人或事，所以救敗啊。舜他的信仁乎！乃躬藉處苦而且民從的，因此韓絕不是子評論說道：聖人的德化乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「歷山之農者侵畔，舜往耕焉，期年，甽畝正」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「歷」、「山」、「農」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「歷山之農者侵畔舜往耕焉期年甽畝正河濱之漁者爭坻舜」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「河濱之漁者爭坻，舜往漁焉，期年，而讓長」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 4,\n      \"canonicalText\": \"或問儒者曰：「方此時也，堯安在？」其人曰：「堯為天子。」「然則仲尼之聖堯奈何？聖人明察在上位，將使天下無姦也。今耕漁不爭，陶器不窳，舜又何德而化？舜之救敗也，則是堯有失也；賢舜則去堯之明察，聖堯則去舜之德化；不可兩得也。楚人有鬻楯與矛者，譽之曰：『吾楯之堅，莫能陷也。』又譽其矛曰：『吾矛之利，於物無不陷也。』或曰：『以子之矛陷子之楯，何如？』其人弗能應也。夫不可陷之楯與無不陷之矛，不可同世而立。今堯、舜之不可兩譽，矛楯之說也。且舜救敗，期年已一過，三年已三過，舜有盡，壽有盡，天下過無已者，以有盡逐無已，所止者寡矣。賞罰使天下必行之，令曰：『中程者賞，弗中程者誅。』令朝至暮變，暮至朝變，十日而海內畢矣，奚待期年？舜猶不以此說堯令從己，乃躬親，不亦無術乎？且夫以身為苦而後化民者，堯、舜之所難也；處勢而驕下者，庸主之所易也。將治天下，釋庸主之所易，道堯、舜之所難，未可與為政也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-4_s-1\",\n        \"han-fei-zi_ch-18_p-4_s-2\",\n        \"han-fei-zi_ch-18_p-4_s-3\",\n        \"han-fei-zi_ch-18_p-4_s-4\",\n        \"han-fei-zi_ch-18_p-4_s-5\",\n        \"han-fei-zi_ch-18_p-4_s-6\",\n        \"han-fei-zi_ch-18_p-4_s-7\",\n        \"han-fei-zi_ch-18_p-4_s-8\",\n        \"han-fei-zi_ch-18_p-4_s-9\",\n        \"han-fei-zi_ch-18_p-4_s-10\",\n        \"han-fei-zi_ch-18_p-4_s-11\",\n        \"han-fei-zi_ch-18_p-4_s-12\",\n        \"han-fei-zi_ch-18_p-4_s-13\",\n        \"han-fei-zi_ch-18_p-4_s-14\",\n        \"han-fei-zi_ch-18_p-4_s-15\",\n        \"han-fei-zi_ch-18_p-4_s-16\",\n        \"han-fei-zi_ch-18_p-4_s-17\",\n        \"han-fei-zi_ch-18_p-4_s-18\",\n        \"han-fei-zi_ch-18_p-4_s-19\",\n        \"han-fei-zi_ch-18_p-4_s-20\",\n        \"han-fei-zi_ch-18_p-4_s-21\",\n        \"han-fei-zi_ch-18_p-4_s-22\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或問儒的人或事說道：方此時啊，堯安在？他的人說道：堯為天子。然則仲尼的聖堯奈何？聖人明察在上位，將使天下無姦啊。今耕漁不爭，陶器不窳，舜又何德而且化？舜的救敗啊，則是堯有失啊；賢舜則去堯的明察，聖堯則去舜的德化；不可兩得啊。楚人有鬻楯與矛的人或事，譽的說道：吾楯的堅，莫能陷啊。又譽他的矛說道：吾矛的利，於物無不陷啊。或說道：以子的矛陷子的楯，何如？他的人弗能應啊。夫不可陷的楯與無不陷的矛，不可同世而且立。今堯、舜的不可兩譽，矛楯的說啊。且舜救敗，期年已一過，三年已三過，舜有盡，壽有盡，天下過無已的人或事，以有盡逐無已，所止的人或事寡矣。賞賜與刑罰使天下必行的，令說道：中程的人或事賞賜，弗中程的人或事誅。令朝至暮變，暮至朝變，十日而且海內畢矣，奚待期年？舜猶不以此說堯令從己，乃躬親，不亦無督察權術乎？再的人或事況且以身為苦而且後化民的人或事，堯、舜的所難啊；處權位威勢而且驕下的人或事，庸主的所易啊。將治天下，釋庸主的所易，道堯、舜的所難，未可與為政啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或問儒者曰：「方此時也，堯安在」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「問」、「儒」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或問儒者曰方此時也堯安在其人曰堯為天子然則仲尼之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」其人曰：「堯為天子」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 5,\n      \"canonicalText\": \"管仲有病，桓公往問之，曰：「仲父病，不幸卒於大命，將奚以告寡人？」管仲曰：「微君言，臣故將謁之。願君去豎刁，除易牙，遠衛公子開方。易牙為君主味，君惟人肉未嘗，易牙烝其子首而進之；夫人情莫不愛其子，今弗愛其子，安能愛君？君妒而好內，豎刁自宮以治內，人情莫不愛其身，身且不愛，安能愛君？聞開方事君十五年，齊、衛之間不容數日行，棄其母久宦不歸，其母不愛，安能愛君？臣聞之：『矜偽不長，蓋虛不久。』願君去此三子者也。」管仲卒死，桓公弗行，及桓公死，蟲出屍不葬。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-5_s-1\",\n        \"han-fei-zi_ch-18_p-5_s-2\",\n        \"han-fei-zi_ch-18_p-5_s-3\",\n        \"han-fei-zi_ch-18_p-5_s-4\",\n        \"han-fei-zi_ch-18_p-5_s-5\",\n        \"han-fei-zi_ch-18_p-5_s-6\",\n        \"han-fei-zi_ch-18_p-5_s-7\",\n        \"han-fei-zi_ch-18_p-5_s-8\",\n        \"han-fei-zi_ch-18_p-5_s-9\",\n        \"han-fei-zi_ch-18_p-5_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"管仲有病，桓公往問的，說道：仲父病，不幸卒於大命，將奚以告寡人？管仲說道：微國君言，臣屬所以將謁的。願國君去豎刁，除易牙，遠衛公子開方。易牙為國君主味，國君惟人肉未嘗，易牙烝他的子首而且進的；夫人情莫不愛他的子，今弗愛他的子，安能愛國君？國君妒而且好內，豎刁自宮以治內，人情莫不愛他的身，身且不愛，安能愛國君？聞開方事國君十五年，齊、衛的間不容數日行，棄他的母久宦不歸，他的母不愛，安能愛國君？臣屬聞的：矜偽不長，蓋虛不久。願國君去此三子的人或事啊。管仲卒死，桓公弗行，及桓公死，蟲出屍不葬。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「管仲有病，桓公往問之，曰：「仲父病，不幸卒於大命，將奚以告寡人」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「管」、「仲」、「有」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「管仲有病桓公往問之曰仲父病不幸卒於大命將奚以告寡」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」管仲曰：「微君言，臣故將謁之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 6,\n      \"canonicalText\": \"或曰：管仲所以見告桓公者，非有度者之言也。所以去豎刁、易牙者，以不愛其身，適君之慾也。曰「不愛其身，安能愛君」，然則臣有盡死力以為其主者，管仲將弗用也。曰「不愛其死力，安能愛君」，是君去忠臣也。且以不愛其身，度其不愛其君，是將以管仲之不能死公子糾度其不死桓公也，是管仲亦在所去之域矣。明主之道不然，設民所欲以求其功，故為爵祿以勸之；設民所惡以禁其姦，故為刑罰以威之。慶賞信而刑罰必，故君舉功於臣，而姦不用於上，雖有豎刁，其奈君何？且臣盡死力以與君市，君垂爵祿以與臣市，君臣之際，非父子之親也，計數之所出也。君有道，則臣盡力而姦不生；無道，則臣上塞主明而下成私。管仲非明此度數於桓公也，使去豎刁，一豎刁又至，非絕姦之道也。且桓公所以身死蟲流出屍不葬者，是臣重也；臣重之實，擅主也。有擅主之臣，則君令不下究，臣情不上通，一人之力能隔君臣之間，使善敗不聞，禍福不通，故有不葬之患也。明主之道，一人不兼官，一官不兼事。卑賤不待尊貴而進，論，大臣不因左右而見。百官修通，群臣輻湊。有賞者君見其功，有罰者君知其罪。見知不悖於前，賞罰不弊於後，安有不葬之患？管仲非明此言於桓公也，使去三子，故曰管仲無度矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-6_s-1\",\n        \"han-fei-zi_ch-18_p-6_s-2\",\n        \"han-fei-zi_ch-18_p-6_s-3\",\n        \"han-fei-zi_ch-18_p-6_s-4\",\n        \"han-fei-zi_ch-18_p-6_s-5\",\n        \"han-fei-zi_ch-18_p-6_s-6\",\n        \"han-fei-zi_ch-18_p-6_s-7\",\n        \"han-fei-zi_ch-18_p-6_s-8\",\n        \"han-fei-zi_ch-18_p-6_s-9\",\n        \"han-fei-zi_ch-18_p-6_s-10\",\n        \"han-fei-zi_ch-18_p-6_s-11\",\n        \"han-fei-zi_ch-18_p-6_s-12\",\n        \"han-fei-zi_ch-18_p-6_s-13\",\n        \"han-fei-zi_ch-18_p-6_s-14\",\n        \"han-fei-zi_ch-18_p-6_s-15\",\n        \"han-fei-zi_ch-18_p-6_s-16\",\n        \"han-fei-zi_ch-18_p-6_s-17\",\n        \"han-fei-zi_ch-18_p-6_s-18\",\n        \"han-fei-zi_ch-18_p-6_s-19\",\n        \"han-fei-zi_ch-18_p-6_s-20\",\n        \"han-fei-zi_ch-18_p-6_s-21\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：管仲所以見告桓公的人或事，絕不是有度的人或事的言啊。所以去豎刁、易牙的人或事，以不愛他的身，適國君的慾啊。說道：不愛他的身，安能愛國君，然則臣屬有盡死力以為他的主的人或事，管仲將弗用啊。說道：不愛他的死力，安能愛國君，是國君去忠臣屬啊。且以不愛他的身，度他的不愛他的國君，是將以管仲的不能死公子糾度他的不死桓公啊，是管仲亦在所去的域矣。明主的道不然，設民所欲以求他的功，所以為爵祿以勸的；設民所惡以禁他的姦，所以為刑刑罰以威的。慶賞賜信而且刑刑罰必，所以國君舉功於臣屬，而且姦不用於上，雖有豎刁，他的奈國君何？且臣屬盡死力以與國君市，國君垂爵祿以與臣屬市，國君臣屬的際，絕不是父子的親啊，計數的所出啊。國君有道，則臣屬盡力而且姦不生；無道，則臣屬上塞主明而且下成私。管仲絕不是明此度數於桓公啊，使去豎刁，一豎刁又至，絕不是絕姦的道啊。且桓公所以身死蟲流出屍不葬的人或事，是臣屬重啊；臣屬重的實，擅主啊。有擅主的臣屬，則國君令不下究，臣屬情不上通，一人的力能隔國君臣屬的間，使善敗不聞，禍福不通，所以有不葬的患啊。明主的道，一人不兼官，一官不兼事。卑賤不待尊貴而且進，論，大臣屬不因左右而且見。百官修通，群臣屬輻湊。有賞賜的人或事國君見他的功，有刑罰的人或事國君知他的罪。見知不悖於前，賞賜與刑罰不弊於後，安有不葬的患？管仲絕不是明此言於桓公啊，使去三子，因此韓絕不是子評論說道：管仲無度矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：管仲所以見告桓公者，非有度者之言也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「管」、「仲」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰管仲所以見告桓公者非有度者之言也所以去豎刁易」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「所以去豎刁、易牙者，以不愛其身，適君之慾也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 7,\n      \"canonicalText\": \"襄子圍於晉陽中，出圍，賞有功者五人，高赫為賞首。張孟談曰：「晉陽之事，赫無大功，今為賞首何也？」襄子曰：「晉陽之事，寡人國家危，社稷殆矣。吾群臣無有不驕侮之意者，惟赫子不失君臣之禮，是以先之。」仲尼聞之曰：「善賞哉襄子！賞一人而天下為人臣者莫敢失禮矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-7_s-1\",\n        \"han-fei-zi_ch-18_p-7_s-2\",\n        \"han-fei-zi_ch-18_p-7_s-3\",\n        \"han-fei-zi_ch-18_p-7_s-4\",\n        \"han-fei-zi_ch-18_p-7_s-5\",\n        \"han-fei-zi_ch-18_p-7_s-6\",\n        \"han-fei-zi_ch-18_p-7_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"襄子圍於晉陽中，出圍，賞賜有功的人或事五人，高赫為賞賜首。張孟談說道：晉陽的事，赫無大功，今為賞賜首何啊？襄子說道：晉陽的事，寡人國家危，社稷殆矣。吾群臣屬無有不驕侮的意的人或事，惟赫子不失國君臣屬的禮，是以先的。仲尼聞的說道：善賞賜哉襄子！賞賜一人而且天下為人臣屬的人或事莫敢失禮矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「襄子圍於晉陽中，出圍，賞有功者五人，高赫為賞首」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「襄」、「子」、「圍」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「襄子圍於晉陽中出圍賞有功者五人高赫為賞首張孟談曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「張孟談曰：「晉陽之事，赫無大功，今為賞首何也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 8,\n      \"canonicalText\": \"或曰：仲尼不知善賞矣。夫善賞罰者，百官不敢侵職，群臣不敢失禮。上設其法，而下無姦詐之心，如此，則可謂善賞罰矣。使襄子於晉陽也，令不行，禁不止，是襄子無國，晉陽無君也，尚誰與守哉？今襄子於晉陽也，知氏灌之，臼竈生龜，而民無反心，是君臣親也；襄子有君臣親之澤，操令行禁止之法，而猶有驕侮之臣，是襄子失罰也。為人臣者，乘事而有功則賞。今赫僅不驕侮而襄子賞之，是失賞也。明主賞不加於無功，罰不加於無罪。今襄子不誅驕侮之臣，而賞無功之赫，安在襄子之善賞也？故曰仲尼不知善賞。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-8_s-1\",\n        \"han-fei-zi_ch-18_p-8_s-2\",\n        \"han-fei-zi_ch-18_p-8_s-3\",\n        \"han-fei-zi_ch-18_p-8_s-4\",\n        \"han-fei-zi_ch-18_p-8_s-5\",\n        \"han-fei-zi_ch-18_p-8_s-6\",\n        \"han-fei-zi_ch-18_p-8_s-7\",\n        \"han-fei-zi_ch-18_p-8_s-8\",\n        \"han-fei-zi_ch-18_p-8_s-9\",\n        \"han-fei-zi_ch-18_p-8_s-10\",\n        \"han-fei-zi_ch-18_p-8_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：仲尼不知善賞賜矣。夫善賞賜與刑罰的人或事，百官不敢侵職，群臣屬不敢失禮。上設他的法規法令，而且下無姦詐的心，如此，則可謂善賞賜與刑罰矣。使襄子於晉陽啊，令不行，禁不止，是襄子無國，晉陽無國君啊，尚誰與守哉？今襄子於晉陽啊，知氏灌的，臼竈生龜，而且民無反心，是國君臣屬親啊；襄子有國君臣屬親的澤，操令行禁止的法規法令，而且猶有驕侮的臣屬，是襄子失刑罰啊。為人臣屬的人或事，乘事而且有功則賞賜。今赫僅不驕侮而且襄子賞賜的，是失賞賜啊。明主賞賜不加於無功，刑罰不加於無罪。今襄子不誅驕侮的臣屬，而且賞賜無功的赫，安在襄子的善賞賜啊？因此韓絕不是子評論說道：仲尼不知善賞賜。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：仲尼不知善賞矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「仲」、「尼」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰仲尼不知善賞矣夫善賞罰者百官不敢侵職群臣不敢」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫善賞罰者，百官不敢侵職，群臣不敢失禮」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 9,\n      \"canonicalText\": \"晉平公與群臣飲，飲酣，乃喟然歎曰：「莫樂為人君！惟其言而莫之違。」師曠侍坐於前，援琴撞之，公披衽而避，琴壞於壁。公曰：「太師誰撞？」師曠曰：「今者有小人言於側者，故撞之。」公曰：「寡人也。」師曠曰：「啞！是非君人者之言也。」左右請除之。公曰：「釋之，以為寡人戒。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-9_s-1\",\n        \"han-fei-zi_ch-18_p-9_s-2\",\n        \"han-fei-zi_ch-18_p-9_s-3\",\n        \"han-fei-zi_ch-18_p-9_s-4\",\n        \"han-fei-zi_ch-18_p-9_s-5\",\n        \"han-fei-zi_ch-18_p-9_s-6\",\n        \"han-fei-zi_ch-18_p-9_s-7\",\n        \"han-fei-zi_ch-18_p-9_s-8\",\n        \"han-fei-zi_ch-18_p-9_s-9\",\n        \"han-fei-zi_ch-18_p-9_s-10\",\n        \"han-fei-zi_ch-18_p-9_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"晉平公與群臣屬飲，飲酣，乃喟然歎說道：莫樂為人國君！惟他的言而且莫的違。師曠侍坐於前，援琴撞的，公披衽而且避，琴壞於壁。公說道：太師誰撞？師曠說道：今的人或事有小人言於側的人或事，所以撞的。公說道：寡人啊。師曠說道：啞！是絕不是國君人的人或事的言啊。左右請除的。公說道：釋的，以為寡人戒。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「晉平公與群臣飲，飲酣，乃喟然歎曰：「莫樂為人君」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「晉」、「平」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「晉平公與群臣飲飲酣乃喟然歎曰莫樂為人君惟其言而莫」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「惟其言而莫之違」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 10,\n      \"canonicalText\": \"或曰：平公失君道，師曠失臣禮。夫非其行而誅其身，君之於臣也；非其行則陳其言，善諫不聽則遠其身者，臣之於君也。今師曠非平公之行，不陳人臣之諫，而行人主之誅，舉琴而親其體，是逆上下之位，而失人臣之禮也。夫為人臣者，君有過則諫，諫不聽則輕爵祿以待之，此人臣之禮義也。今師曠非平公之過，舉琴而親其體，雖嚴父不加於子，而師曠行之於君，此大逆之術也。臣行大逆，平公喜而聽之，是失君道也。故平公之跡，不可明也，使人主過於聽而不悟其失。師曠之行亦不可明也，使姦臣襲極諫而飾弒君之道。不可謂兩明，此為兩過。故曰：平公失君道，師曠亦失臣禮矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-10_s-1\",\n        \"han-fei-zi_ch-18_p-10_s-2\",\n        \"han-fei-zi_ch-18_p-10_s-3\",\n        \"han-fei-zi_ch-18_p-10_s-4\",\n        \"han-fei-zi_ch-18_p-10_s-5\",\n        \"han-fei-zi_ch-18_p-10_s-6\",\n        \"han-fei-zi_ch-18_p-10_s-7\",\n        \"han-fei-zi_ch-18_p-10_s-8\",\n        \"han-fei-zi_ch-18_p-10_s-9\",\n        \"han-fei-zi_ch-18_p-10_s-10\",\n        \"han-fei-zi_ch-18_p-10_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：平公失國君道，師曠失臣屬禮。夫絕不是他的行而且誅他的身，國君的於臣屬啊；絕不是他的行則陳他的言，善諫不聽則遠他的身的人或事，臣屬的於國君啊。今師曠絕不是平公的行，不陳人臣屬的諫，而且行人主的誅，舉琴而且親他的體，是逆上下的位，而且失人臣屬的禮啊。夫為人臣屬的人或事，國君有過則諫，諫不聽則輕爵祿以待的，此人臣屬的禮義啊。今師曠絕不是平公的過，舉琴而且親他的體，雖嚴父不加於子，而且師曠行的於國君，此大逆的督察權術啊。臣屬行大逆，平公喜而且聽的，是失國君道啊。所以平公的跡，不可明啊，使人主過於聽而且不悟他的失。師曠的行亦不可明啊，使姦臣屬襲極諫而且飾弒國君的道。不可謂兩明，此為兩過。因此韓絕不是子評論說道：平公失國君道，師曠亦失臣屬禮矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：平公失君道，師曠失臣禮」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「平」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰平公失君道師曠失臣禮夫非其行而誅其身君之於臣」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫非其行而誅其身，君之於臣也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 11,\n      \"canonicalText\": \"齊桓公時，有處士曰小臣稷，桓公三往而弗得見。桓公曰：「吾聞布衣之士，不輕爵祿，無以易萬乘之主；萬乘之主，不好仁義，亦無以下布衣之士。」於是五往乃得見之。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-11_s-1\",\n        \"han-fei-zi_ch-18_p-11_s-2\",\n        \"han-fei-zi_ch-18_p-11_s-3\",\n        \"han-fei-zi_ch-18_p-11_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊桓公時，有處士說道：小臣屬稷，桓公三往而且弗得見。桓公說道：吾聞布衣的士，不輕爵祿，無以易萬乘的主；萬乘的主，不好仁義，亦無以下布衣的士。於是五往乃得見的。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「齊桓公時，有處士曰小臣稷，桓公三往而弗得見」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「齊」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「齊桓公時有處士曰小臣稷桓公三往而弗得見桓公曰吾聞」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「桓公曰：「吾聞布衣之士，不輕爵祿，無以易萬乘之主」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 12,\n      \"canonicalText\": \"或曰：桓公不知仁義。夫仁義者，憂天下之害，趨一國之患，不避卑辱謂之仁義。故伊尹以中國為亂，道為宰於湯；百里奚以秦為亂，道為虜於穆公；皆憂天下之害，趨一國之患，不辭卑辱，故謂之仁義。今桓公以萬乘之勢，下匹夫之士，將欲憂齊國，而小臣不行，見小臣之忘民也，忘民不可謂仁義。仁義者，不失人臣之禮，不敗君臣之位者也。是故四封之內，執會而朝名曰臣，臣吏分職受事名曰萌。今小臣在民萌之眾，而逆君上之慾，故不可謂仁義。仁義不在焉，桓公又從而禮之。使小臣有智能而遁桓公，是隱也，宜刑；若無智能而虛驕矜桓公，是誣也，宜戮；小臣之行，非刑則戮。桓公不能領臣主之理，而禮刑戮之人，是桓公以輕上侮君之俗教於齊國也，非所以為治也。故曰：桓公不知仁義。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-12_s-1\",\n        \"han-fei-zi_ch-18_p-12_s-2\",\n        \"han-fei-zi_ch-18_p-12_s-3\",\n        \"han-fei-zi_ch-18_p-12_s-4\",\n        \"han-fei-zi_ch-18_p-12_s-5\",\n        \"han-fei-zi_ch-18_p-12_s-6\",\n        \"han-fei-zi_ch-18_p-12_s-7\",\n        \"han-fei-zi_ch-18_p-12_s-8\",\n        \"han-fei-zi_ch-18_p-12_s-9\",\n        \"han-fei-zi_ch-18_p-12_s-10\",\n        \"han-fei-zi_ch-18_p-12_s-11\",\n        \"han-fei-zi_ch-18_p-12_s-12\",\n        \"han-fei-zi_ch-18_p-12_s-13\",\n        \"han-fei-zi_ch-18_p-12_s-14\",\n        \"han-fei-zi_ch-18_p-12_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：桓公不知仁義。夫仁義的人或事，憂天下的害，趨一國的患，不避卑辱謂的仁義。所以伊尹以中國為亂，道為宰於湯；百里奚以秦為亂，道為虜於穆公；皆憂天下的害，趨一國的患，不辭卑辱，所以謂的仁義。今桓公以萬乘的權位威勢，下匹夫的士，將欲憂齊國，而且小臣屬不行，見小臣屬的忘民啊，忘民不可謂仁義。仁義的人或事，不失人臣屬的禮，不敗國君臣屬的位的人或事啊。正因為如此四封的內，執會而且朝名說道：臣屬，臣屬吏分職受事名說道：萌。今小臣屬在民萌的眾，而且逆國君上的慾，所以不可謂仁義。仁義不在焉，桓公又從而且禮的。使小臣屬有智能而且遁桓公，是隱啊，宜刑；若無智能而且虛驕矜桓公，是誣啊，宜戮；小臣屬的行，絕不是刑則戮。桓公不能領臣屬主的理，而且禮刑戮的人，是桓公以輕上侮國君的俗教於齊國啊，絕不是所以為治啊。因此韓絕不是子評論說道：桓公不知仁義。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：桓公不知仁義」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「桓」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰桓公不知仁義夫仁義者憂天下之害趨一國之患不避」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫仁義者，憂天下之害，趨一國之患，不避卑辱謂之仁義」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 13,\n      \"canonicalText\": \"靡笄之役，韓獻子將斬人，郤獻子聞之，駕往救之，比至，則已斬之矣。郤子因曰：「胡不以徇？」其僕曰：「曩不將救之乎？」郤子曰：「吾敢不分謗乎？」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-13_s-1\",\n        \"han-fei-zi_ch-18_p-13_s-2\",\n        \"han-fei-zi_ch-18_p-13_s-3\",\n        \"han-fei-zi_ch-18_p-13_s-4\",\n        \"han-fei-zi_ch-18_p-13_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"靡笄的役，韓獻子將斬人，郤獻子聞的，駕往救的，比至，則已斬的矣。郤子因說道：胡不以徇？他的僕說道：曩不將救的乎？郤子說道：吾敢不分謗乎？\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「靡笄之役，韓獻子將斬人，郤獻子聞之，駕往救之，比至，則已斬之矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「靡」、「笄」、「役」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「靡笄之役韓獻子將斬人郤獻子聞之駕往救之比至則已斬」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「郤子因曰：「胡不以徇」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 14,\n      \"canonicalText\": \"或曰：郤子言不可不察也，非分謗也。韓子之所斬也，若罪人則不可救，救罪人，法之所以敗也，法敗則國亂；若非罪人，則勸之以徇，勸之以徇，是重不辜也，重不辜，民所以起怨者也，民怨則國危。郤子之言，非危則亂，不可不察也。且韓子之所斬若罪人，郤子奚分焉？斬若非罪人，則已斬之矣，而郤子乃至，是韓子之謗已成，而郤子且後至也。夫郤子曰「以徇」，不足以分斬人之謗，而又生徇之謗。是子言分謗也？昔者紂為炮烙，崇侯、惡來又曰斬涉者之脛也，奚分於紂之謗？且民之望於上也甚矣，韓子弗得，且望郤子之得之也；今郤子俱弗得，則民絕望於上矣，故曰：郤子之言非分謗也，益謗也。且郤子之往救罪也，以韓子為非也，不道其所以為非，而勸之「以徇」，是使韓子不知其過也。夫下使民望絕於上，又使韓子不知其失，吾未得郤子之所以分謗者也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-14_s-1\",\n        \"han-fei-zi_ch-18_p-14_s-2\",\n        \"han-fei-zi_ch-18_p-14_s-3\",\n        \"han-fei-zi_ch-18_p-14_s-4\",\n        \"han-fei-zi_ch-18_p-14_s-5\",\n        \"han-fei-zi_ch-18_p-14_s-6\",\n        \"han-fei-zi_ch-18_p-14_s-7\",\n        \"han-fei-zi_ch-18_p-14_s-8\",\n        \"han-fei-zi_ch-18_p-14_s-9\",\n        \"han-fei-zi_ch-18_p-14_s-10\",\n        \"han-fei-zi_ch-18_p-14_s-11\",\n        \"han-fei-zi_ch-18_p-14_s-12\",\n        \"han-fei-zi_ch-18_p-14_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：郤子言不可不察啊，絕不是分謗啊。韓子的所斬啊，若罪人則不可救，救罪人，法規法令的所以敗啊，法規法令敗則國亂；若絕不是罪人，則勸的以徇，勸的以徇，是重不辜啊，重不辜，民所以起怨的人或事啊，民怨則國危。郤子的言，絕不是危則亂，不可不察啊。且韓子的所斬若罪人，郤子奚分焉？斬若絕不是罪人，則已斬的矣，而且郤子乃至，是韓子的謗已成，而且郤子且後至啊。夫郤子說道：以徇，不足以分斬人的謗，而且又生徇的謗。是子言分謗啊？昔的人或事紂為炮烙，崇侯、惡來又說道：斬涉的人或事的脛啊，奚分於紂的謗？且民的望於上啊甚矣，韓子弗得，且望郤子的得的啊；今郤子俱弗得，則民絕望於上矣，因此韓絕不是子評論說道：郤子的言絕不是分謗啊，益謗啊。且郤子的往救罪啊，以韓子為絕不是啊，不道他的所以為絕不是，而且勸的以徇，是使韓子不知他的過啊。夫下使民望絕於上，又使韓子不知他的失，吾未得郤子的所以分謗的人或事啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：郤子言不可不察也，非分謗也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「郤」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰郤子言不可不察也非分謗也韓子之所斬也若罪人則」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「韓子之所斬也，若罪人則不可救，救罪人，法之所以敗也，法敗則國亂」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 15,\n      \"canonicalText\": \"桓公解管仲之束縛而相之。管仲曰：「臣有寵矣，然而臣卑。」公曰：「使子立高、國之上。」管仲曰：「臣貴矣，然而臣貧。」公曰：「使子有三歸之家。」管仲曰：「臣富矣，然而臣疏。」於是立以為仲父。霄略曰：「管仲以賤為不可以治國，故請高、國之上；以貧為不可以治富，故請三歸；以疏為不可以治親，故處仲父。管仲非貪，以便治也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-15_s-1\",\n        \"han-fei-zi_ch-18_p-15_s-2\",\n        \"han-fei-zi_ch-18_p-15_s-3\",\n        \"han-fei-zi_ch-18_p-15_s-4\",\n        \"han-fei-zi_ch-18_p-15_s-5\",\n        \"han-fei-zi_ch-18_p-15_s-6\",\n        \"han-fei-zi_ch-18_p-15_s-7\",\n        \"han-fei-zi_ch-18_p-15_s-8\",\n        \"han-fei-zi_ch-18_p-15_s-9\",\n        \"han-fei-zi_ch-18_p-15_s-10\",\n        \"han-fei-zi_ch-18_p-15_s-11\",\n        \"han-fei-zi_ch-18_p-15_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"桓公解管仲的束縛而且相的。管仲說道：臣屬有寵矣，然而且臣屬卑。公說道：使子立高、國的上。管仲說道：臣屬貴矣，然而且臣屬貧。公說道：使子有三歸的家。管仲說道：臣屬富矣，然而且臣屬疏。於是立以為仲父。霄略說道：管仲以賤為不可以治國，所以請高、國的上；以貧為不可以治富，所以請三歸；以疏為不可以治親，所以處仲父。管仲絕不是貪，以便治啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「桓公解管仲之束縛而相之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「桓」、「公」、「解」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「桓公解管仲之束縛而相之管仲曰臣有寵矣然而臣卑公曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「管仲曰：「臣有寵矣，然而臣卑」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 16,\n      \"canonicalText\": \"或曰：今使臧獲奉君令詔卿相，莫敢不聽，非卿相卑而臧獲尊也，主令所加，莫敢不從也。今使管仲之治，不緣桓公，是無君也，國無君不可以為治。若負桓公之威，下桓公之令，是臧獲之所以信也，奚待高、國、仲父之尊而後行哉？當世之行事都丞之下徵令者，不闢尊貴，不就卑賤。故行之而法者，雖巷伯信乎卿相；行之而非法者，雖大吏詘乎民萌。今管仲不務尊主明法，而事增寵益爵，是非管仲貪欲富貴，必闇而不知術也。故曰：管仲有失行，霄略有過譽。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-16_s-1\",\n        \"han-fei-zi_ch-18_p-16_s-2\",\n        \"han-fei-zi_ch-18_p-16_s-3\",\n        \"han-fei-zi_ch-18_p-16_s-4\",\n        \"han-fei-zi_ch-18_p-16_s-5\",\n        \"han-fei-zi_ch-18_p-16_s-6\",\n        \"han-fei-zi_ch-18_p-16_s-7\",\n        \"han-fei-zi_ch-18_p-16_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：今使臧獲奉國君令詔卿相，莫敢不聽，絕不是卿相卑而且臧獲尊啊，主令所加，莫敢不從啊。今使管仲的治，不緣桓公，是無國君啊，國無國君不可以為治。若負桓公的威，下桓公的令，是臧獲的所以信啊，奚待高、國、仲父的尊而且後行哉？當世的行事都丞的下徵令的人或事，不闢尊貴，不就卑賤。所以行的而且法規法令的人或事，雖巷伯信乎卿相；行的而且絕不是法規法令的人或事，雖大吏詘乎民萌。今管仲不務尊主明法規法令，而且事增寵益爵，是絕不是管仲貪欲富貴，必闇而且不知督察權術啊。因此韓絕不是子評論說道：管仲有失行，霄略有過譽。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：今使臧獲奉君令詔卿相，莫敢不聽，非卿相卑而臧獲尊也，主令所加，莫敢不從也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「今」、「使」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰今使臧獲奉君令詔卿相莫敢不聽非卿相卑而臧獲尊」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「今使管仲之治，不緣桓公，是無君也，國無君不可以為治」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-17\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 17,\n      \"canonicalText\": \"韓宣王問於樛留：「吾欲兩用公仲、公叔其可乎？」樛留對曰：「昔魏兩用樓、翟而亡西河，楚兩用昭、景而亡鄢、郢，今君兩用公仲、公叔，此必將爭事而外市，則國必憂矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-17_s-1\",\n        \"han-fei-zi_ch-18_p-17_s-2\",\n        \"han-fei-zi_ch-18_p-17_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"韓宣王問於樛留：吾欲兩用公仲、公叔他的可乎？樛留對說道：昔魏兩用樓、翟而且亡西河，楚兩用昭、景而且亡鄢、郢，今君主統治者兩用公仲、公叔，此必將爭事而且外市，則國必憂矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「韓宣王問於樛留：「吾欲兩用公仲、公叔其可乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「宣」、「王」、「問」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「韓宣王問於樛留吾欲兩用公仲公叔其可乎樛留對曰昔魏」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」樛留對曰：「昔魏兩用樓、翟而亡西河，楚兩用昭、景而亡鄢、郢，今君兩用公仲、公叔，此必將爭事而外市，則國必憂矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"order\": 18,\n      \"canonicalText\": \"或曰：昔者齊桓公兩用管仲、鮑叔，成湯兩用伊尹、仲虺。夫兩用臣者國之憂，則是桓公不霸，成湯不王也。湣王一用淖齒而手死乎東廟，主父一用李兌，減食而死。主有術，兩用不為患；無術，兩用則爭事而外市，一則專制而劫弒。今留無術以規上，使其主去兩用一，是不有西河、鄢、郢之憂，則必有身死減食之患。是樛留未有善以知言也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-18_p-18_s-1\",\n        \"han-fei-zi_ch-18_p-18_s-2\",\n        \"han-fei-zi_ch-18_p-18_s-3\",\n        \"han-fei-zi_ch-18_p-18_s-4\",\n        \"han-fei-zi_ch-18_p-18_s-5\",\n        \"han-fei-zi_ch-18_p-18_s-6\",\n        \"han-fei-zi_ch-18_p-18_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：昔的人或事齊桓公兩用管仲、鮑叔，成湯兩用伊尹、仲虺。夫兩用臣屬的人或事國的憂，則是桓公不霸，成湯不王啊。湣王一用淖齒而且手死乎東廟，主父一用李兌，減食而且死。主有督察權術，兩用不為患；無督察權術，兩用則爭事而且外市，一則專制而且劫弒。今留無督察權術以規上，使他的主去兩用一，是不有西河、鄢、郢的憂，則必有身死減食的患。是樛留未有善以知言啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難一〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：昔者齊桓公兩用管仲、鮑叔，成湯兩用伊尹、仲虺」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「昔」、「齊」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰昔者齊桓公兩用管仲鮑叔成湯兩用伊尹仲虺夫兩用」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫兩用臣者國之憂，則是桓公不霸，成湯不王也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"晉文公將與楚人戰，召舅犯問之，曰：「吾將與楚人戰，彼眾我寡，為之奈何？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"」舅犯曰：「臣聞之，繁禮君子，不厭忠信；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"戰陣之閒，不厭詐偽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"君其詐之而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"」文公辭舅犯，因召雍季而問之，曰：「我將與楚人戰，彼眾我寡，為之奈何？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"」雍季對曰：「焚林而田，偷取多獸，後必無獸；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"以詐遇民，偷取一時，後必無復。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"」文公曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"」辭雍季，以舅犯之謀與楚人戰以敗之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"歸而行爵，先雍季而後舅犯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"群臣曰：「城濮之事，舅犯謀也，夫用其言而後其身可乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 12,\n      \"canonicalText\": \"」文公曰：「此非君所知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 13,\n      \"canonicalText\": \"夫舅犯言，一時之權也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 14,\n      \"canonicalText\": \"雍季言，萬世之利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 15,\n      \"canonicalText\": \"」仲尼聞之，曰：「文公之霸也宜哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 16,\n      \"canonicalText\": \"既知一時之權，又知萬世之利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-1_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-1\",\n      \"order\": 17,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：雍季之對，不當文公之問。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"凡對問者，有因問小大緩急而對也，所問高大而對以卑狹，則明主弗受也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"今文公問以少遇眾，而對曰「後必無復」，此非所以應也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"且文公不知一時之權，又不知萬世之利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"戰而勝，則國安而身定，兵強而威立，雖有後復，莫大於此，萬世之利，奚患不至？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"戰而不勝，則國亡兵弱，身死名息，拔拂今日之死不及，安暇待萬世之利？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"待萬世之利在今日之勝，今日之勝在詐於敵，詐敵，萬世之利而已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"故曰：雍季之對不當文公之問。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"且文公又不知舅犯之言，舅犯所謂不厭詐偽者，不謂詐其民，請詐其敵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"敵者，所伐之國也，後雖無復，何傷哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"文公之所以先雍季者，以其功耶？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"則所以勝楚破軍者，舅犯之謀也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"以其善言耶？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 14,\n      \"canonicalText\": \"則雍季乃道其後之無復也，此未有善言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 15,\n      \"canonicalText\": \"舅犯則以兼之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 16,\n      \"canonicalText\": \"舅犯曰「繁禮君子，不厭忠信」者，忠、所以愛其下也，信、所以不欺其民也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 17,\n      \"canonicalText\": \"夫既以愛而不欺矣，言孰善於此？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 18,\n      \"canonicalText\": \"然必曰出於詐偽者，軍旅之計也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 19,\n      \"canonicalText\": \"舅犯前有善言，後有戰勝，故舅犯有二功而後論，雍季無一焉而先賞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-2_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-2\",\n      \"order\": 20,\n      \"canonicalText\": \"「文公之霸，不亦宜乎，」仲尼不知善賞也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"歷山之農者侵畔，舜往耕焉，期年，甽畝正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"河濱之漁者爭坻，舜往漁焉，期年，而讓長。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"東夷之陶者器苦窳，舜往陶焉，期年而器牢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"仲尼歎曰：「耕、漁與陶，非舜官也，而舜往為之者，所以救敗也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"舜其信仁乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"乃躬藉處苦而民從之，故曰：聖人之德化乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-3_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"或問儒者曰：「方此時也，堯安在？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"」其人曰：「堯為天子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"」「然則仲尼之聖堯奈何？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"聖人明察在上位，將使天下無姦也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"今耕漁不爭，陶器不窳，舜又何德而化？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"舜之救敗也，則是堯有失也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"賢舜則去堯之明察，聖堯則去舜之德化；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"不可兩得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"楚人有鬻楯與矛者，譽之曰：『吾楯之堅，莫能陷也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"』又譽其矛曰：『吾矛之利，於物無不陷也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"』或曰：『以子之矛陷子之楯，何如？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"』其人弗能應也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"夫不可陷之楯與無不陷之矛，不可同世而立。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 14,\n      \"canonicalText\": \"今堯、舜之不可兩譽，矛楯之說也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 15,\n      \"canonicalText\": \"且舜救敗，期年已一過，三年已三過，舜有盡，壽有盡，天下過無已者，以有盡逐無已，所止者寡矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 16,\n      \"canonicalText\": \"賞罰使天下必行之，令曰：『中程者賞，弗中程者誅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 17,\n      \"canonicalText\": \"』令朝至暮變，暮至朝變，十日而海內畢矣，奚待期年？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 18,\n      \"canonicalText\": \"舜猶不以此說堯令從己，乃躬親，不亦無術乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 19,\n      \"canonicalText\": \"且夫以身為苦而後化民者，堯、舜之所難也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 20,\n      \"canonicalText\": \"處勢而驕下者，庸主之所易也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 21,\n      \"canonicalText\": \"將治天下，釋庸主之所易，道堯、舜之所難，未可與為政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-4_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-4\",\n      \"order\": 22,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"管仲有病，桓公往問之，曰：「仲父病，不幸卒於大命，將奚以告寡人？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"」管仲曰：「微君言，臣故將謁之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"願君去豎刁，除易牙，遠衛公子開方。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"易牙為君主味，君惟人肉未嘗，易牙烝其子首而進之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"夫人情莫不愛其子，今弗愛其子，安能愛君？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"君妒而好內，豎刁自宮以治內，人情莫不愛其身，身且不愛，安能愛君？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"聞開方事君十五年，齊、衛之間不容數日行，棄其母久宦不歸，其母不愛，安能愛君？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"臣聞之：『矜偽不長，蓋虛不久。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"』願君去此三子者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-5_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"」管仲卒死，桓公弗行，及桓公死，蟲出屍不葬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：管仲所以見告桓公者，非有度者之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"所以去豎刁、易牙者，以不愛其身，適君之慾也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"曰「不愛其身，安能愛君」，然則臣有盡死力以為其主者，管仲將弗用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"曰「不愛其死力，安能愛君」，是君去忠臣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"且以不愛其身，度其不愛其君，是將以管仲之不能死公子糾度其不死桓公也，是管仲亦在所去之域矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"明主之道不然，設民所欲以求其功，故為爵祿以勸之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"設民所惡以禁其姦，故為刑罰以威之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"慶賞信而刑罰必，故君舉功於臣，而姦不用於上，雖有豎刁，其奈君何？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"且臣盡死力以與君市，君垂爵祿以與臣市，君臣之際，非父子之親也，計數之所出也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"君有道，則臣盡力而姦不生；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"無道，則臣上塞主明而下成私。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"管仲非明此度數於桓公也，使去豎刁，一豎刁又至，非絕姦之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"且桓公所以身死蟲流出屍不葬者，是臣重也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 14,\n      \"canonicalText\": \"臣重之實，擅主也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 15,\n      \"canonicalText\": \"有擅主之臣，則君令不下究，臣情不上通，一人之力能隔君臣之間，使善敗不聞，禍福不通，故有不葬之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 16,\n      \"canonicalText\": \"明主之道，一人不兼官，一官不兼事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 17,\n      \"canonicalText\": \"卑賤不待尊貴而進，論，大臣不因左右而見。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 18,\n      \"canonicalText\": \"百官修通，群臣輻湊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 19,\n      \"canonicalText\": \"有賞者君見其功，有罰者君知其罪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 20,\n      \"canonicalText\": \"見知不悖於前，賞罰不弊於後，安有不葬之患？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-6_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-6\",\n      \"order\": 21,\n      \"canonicalText\": \"管仲非明此言於桓公也，使去三子，故曰管仲無度矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"襄子圍於晉陽中，出圍，賞有功者五人，高赫為賞首。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"張孟談曰：「晉陽之事，赫無大功，今為賞首何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"」襄子曰：「晉陽之事，寡人國家危，社稷殆矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"吾群臣無有不驕侮之意者，惟赫子不失君臣之禮，是以先之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"」仲尼聞之曰：「善賞哉襄子！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"賞一人而天下為人臣者莫敢失禮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-7_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：仲尼不知善賞矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"夫善賞罰者，百官不敢侵職，群臣不敢失禮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"上設其法，而下無姦詐之心，如此，則可謂善賞罰矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"使襄子於晉陽也，令不行，禁不止，是襄子無國，晉陽無君也，尚誰與守哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"今襄子於晉陽也，知氏灌之，臼竈生龜，而民無反心，是君臣親也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"襄子有君臣親之澤，操令行禁止之法，而猶有驕侮之臣，是襄子失罰也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"為人臣者，乘事而有功則賞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"今赫僅不驕侮而襄子賞之，是失賞也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"明主賞不加於無功，罰不加於無罪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"今襄子不誅驕侮之臣，而賞無功之赫，安在襄子之善賞也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-8_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"故曰仲尼不知善賞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"晉平公與群臣飲，飲酣，乃喟然歎曰：「莫樂為人君！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"惟其言而莫之違。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"」師曠侍坐於前，援琴撞之，公披衽而避，琴壞於壁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"公曰：「太師誰撞？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"」師曠曰：「今者有小人言於側者，故撞之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"」公曰：「寡人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"」師曠曰：「啞！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"是非君人者之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 9,\n      \"canonicalText\": \"」左右請除之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 10,\n      \"canonicalText\": \"公曰：「釋之，以為寡人戒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-9_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-9\",\n      \"order\": 11,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：平公失君道，師曠失臣禮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"夫非其行而誅其身，君之於臣也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"非其行則陳其言，善諫不聽則遠其身者，臣之於君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"今師曠非平公之行，不陳人臣之諫，而行人主之誅，舉琴而親其體，是逆上下之位，而失人臣之禮也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"夫為人臣者，君有過則諫，諫不聽則輕爵祿以待之，此人臣之禮義也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"今師曠非平公之過，舉琴而親其體，雖嚴父不加於子，而師曠行之於君，此大逆之術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"臣行大逆，平公喜而聽之，是失君道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"故平公之跡，不可明也，使人主過於聽而不悟其失。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"師曠之行亦不可明也，使姦臣襲極諫而飾弒君之道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"不可謂兩明，此為兩過。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-10_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"故曰：平公失君道，師曠亦失臣禮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"齊桓公時，有處士曰小臣稷，桓公三往而弗得見。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"桓公曰：「吾聞布衣之士，不輕爵祿，無以易萬乘之主；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"萬乘之主，不好仁義，亦無以下布衣之士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"」於是五往乃得見之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：桓公不知仁義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"夫仁義者，憂天下之害，趨一國之患，不避卑辱謂之仁義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"故伊尹以中國為亂，道為宰於湯；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"百里奚以秦為亂，道為虜於穆公；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"皆憂天下之害，趨一國之患，不辭卑辱，故謂之仁義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"今桓公以萬乘之勢，下匹夫之士，將欲憂齊國，而小臣不行，見小臣之忘民也，忘民不可謂仁義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"仁義者，不失人臣之禮，不敗君臣之位者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"是故四封之內，執會而朝名曰臣，臣吏分職受事名曰萌。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"今小臣在民萌之眾，而逆君上之慾，故不可謂仁義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"仁義不在焉，桓公又從而禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"使小臣有智能而遁桓公，是隱也，宜刑；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 12,\n      \"canonicalText\": \"若無智能而虛驕矜桓公，是誣也，宜戮；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 13,\n      \"canonicalText\": \"小臣之行，非刑則戮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 14,\n      \"canonicalText\": \"桓公不能領臣主之理，而禮刑戮之人，是桓公以輕上侮君之俗教於齊國也，非所以為治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-12_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-12\",\n      \"order\": 15,\n      \"canonicalText\": \"故曰：桓公不知仁義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"靡笄之役，韓獻子將斬人，郤獻子聞之，駕往救之，比至，則已斬之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"郤子因曰：「胡不以徇？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"」其僕曰：「曩不將救之乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-13_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"」郤子曰：「吾敢不分謗乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-13_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：郤子言不可不察也，非分謗也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"韓子之所斬也，若罪人則不可救，救罪人，法之所以敗也，法敗則國亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"若非罪人，則勸之以徇，勸之以徇，是重不辜也，重不辜，民所以起怨者也，民怨則國危。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"郤子之言，非危則亂，不可不察也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"且韓子之所斬若罪人，郤子奚分焉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 6,\n      \"canonicalText\": \"斬若非罪人，則已斬之矣，而郤子乃至，是韓子之謗已成，而郤子且後至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 7,\n      \"canonicalText\": \"夫郤子曰「以徇」，不足以分斬人之謗，而又生徇之謗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 8,\n      \"canonicalText\": \"是子言分謗也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 9,\n      \"canonicalText\": \"昔者紂為炮烙，崇侯、惡來又曰斬涉者之脛也，奚分於紂之謗？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 10,\n      \"canonicalText\": \"且民之望於上也甚矣，韓子弗得，且望郤子之得之也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 11,\n      \"canonicalText\": \"今郤子俱弗得，則民絕望於上矣，故曰：郤子之言非分謗也，益謗也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 12,\n      \"canonicalText\": \"且郤子之往救罪也，以韓子為非也，不道其所以為非，而勸之「以徇」，是使韓子不知其過也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-14_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-14\",\n      \"order\": 13,\n      \"canonicalText\": \"夫下使民望絕於上，又使韓子不知其失，吾未得郤子之所以分謗者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"桓公解管仲之束縛而相之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"管仲曰：「臣有寵矣，然而臣卑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 3,\n      \"canonicalText\": \"」公曰：「使子立高、國之上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 4,\n      \"canonicalText\": \"」管仲曰：「臣貴矣，然而臣貧。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 5,\n      \"canonicalText\": \"」公曰：「使子有三歸之家。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 6,\n      \"canonicalText\": \"」管仲曰：「臣富矣，然而臣疏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 7,\n      \"canonicalText\": \"」於是立以為仲父。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 8,\n      \"canonicalText\": \"霄略曰：「管仲以賤為不可以治國，故請高、國之上；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 9,\n      \"canonicalText\": \"以貧為不可以治富，故請三歸；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 10,\n      \"canonicalText\": \"以疏為不可以治親，故處仲父。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 11,\n      \"canonicalText\": \"管仲非貪，以便治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-15_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-15\",\n      \"order\": 12,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：今使臧獲奉君令詔卿相，莫敢不聽，非卿相卑而臧獲尊也，主令所加，莫敢不從也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"今使管仲之治，不緣桓公，是無君也，國無君不可以為治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"若負桓公之威，下桓公之令，是臧獲之所以信也，奚待高、國、仲父之尊而後行哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"當世之行事都丞之下徵令者，不闢尊貴，不就卑賤。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"故行之而法者，雖巷伯信乎卿相；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"行之而非法者，雖大吏詘乎民萌。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"今管仲不務尊主明法，而事增寵益爵，是非管仲貪欲富貴，必闇而不知術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-16_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"故曰：管仲有失行，霄略有過譽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-17_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"韓宣王問於樛留：「吾欲兩用公仲、公叔其可乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-17_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"」樛留對曰：「昔魏兩用樓、翟而亡西河，楚兩用昭、景而亡鄢、郢，今君兩用公仲、公叔，此必將爭事而外市，則國必憂矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-17_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：昔者齊桓公兩用管仲、鮑叔，成湯兩用伊尹、仲虺。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"夫兩用臣者國之憂，則是桓公不霸，成湯不王也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"湣王一用淖齒而手死乎東廟，主父一用李兌，減食而死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"主有術，兩用不為患；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"無術，兩用則爭事而外市，一則專制而劫弒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"今留無術以規上，使其主去兩用一，是不有西河、鄢、郢之憂，則必有身死減食之患。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-18_p-18_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-18\",\n      \"passageId\": \"han-fei-zi_ch-18_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"是樛留未有善以知言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
